public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a boolean array to keep track of the visited nodes
    boolean[] visited = new boolean[n];

    // Initialize a variable to keep track of the minimum time
    int minTime = 0;

    // Start at node 0
    queue.add(0);
    visited[0] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int current = queue.poll();

        // If the current node has an apple, add its time to the minimum time
        if (hasApple[current]) {
            minTime += current;
        }

        // Loop through the neighbors of the current node
        for (int neighbor : graph.getNeighbors(current)) {
            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    // Return the minimum time
    return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (s.length() > 0) {
        // Step 1: Pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        result.append(smallest);
        s = s.substring(1);

        // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it
        int smallestIndex = s.indexOf(smallest);
        while (smallestIndex < s.length() - 1 && s.charAt(smallestIndex + 1) <= smallest) {
            smallestIndex++;
        }
        if (smallestIndex < s.length()) {
            result.append(s.charAt(smallestIndex));
            s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
        }

        // Step 3: Repeat step 2 until you cannot pick more characters
        while (s.length() > 0) {
            // Step 4: Pick the largest character from s and append it to the result
            char largest = s.charAt(s.length() - 1);
            result.append(largest);
            s = s.substring(0, s.length() - 1);

            // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it
            int largestIndex = s.lastIndexOf(largest);
            while (largestIndex > 0 && s.charAt(largestIndex - 1) >= largest) {
                largestIndex--;
            }
            if (largestIndex > 0) {
                result.append(s.charAt(largestIndex - 1));
                s = s.substring(0, largestIndex) + s.substring(largestIndex);
            }
        }
    }
    return result.toString();
}

