public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] dp = new int[n + 1];
    int[][] dp2 = new int[n + 1][n + 1];
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (s.charAt(i - 1) == s.charAt(j - 1)) {
                dp2[i][j] = dp[i - 1] + 1;
            } else {
                dp2[i][j] = Math.max(dp[i - 1], dp[j - 1]);
            }
        }
    }
    return dp2[n][n];
}

